fn print_help() {
    println!("A fast Markdown linter written in Rust (Ru(st) MarkDown Linter)");
    println!();
    println!("Usage: executable [OPTIONS] <COMMAND>");
    println!();
    println!("Commands:");
    println!("  check        Lint Markdown files and print warnings/errors");
    println!("  fmt          Format Markdown files (alias for check --fix)");
    println!("  init         Initialize a new configuration file");
    println!("  rule         Show information about a rule or list all rules");
    println!("  explain      Explain a rule with detailed information and examples");
    println!("  config       Show configuration or query a specific key");
    println!("  server       Start the Language Server Protocol server");
    println!("  schema       Generate or check JSON schema for rumdl.toml");
    println!("  import       Import and convert markdownlint configuration files");
    println!("  vscode       Install the rumdl VS Code extension");
    println!("  completions  Generate shell completion scripts");
    println!("  clean        Clear the cache");
    println!("  version      Show version information");
    println!("  help         Print this message or the help of the given subcommand(s)");
    println!();
    println!("Options:");
    println!("      --color <COLOR>    Control colored output: auto, always, never [default: auto] [possible values: auto, always, never]");
    println!("      --config <CONFIG>  Path to configuration file");
    println!("      --no-config        Ignore all configuration files and use built-in defaults");
    println!("      --isolated         Ignore all configuration files (alias for --no-config)");
    println!("  -h, --help             Print help");
    println!("  -V, --version          Print version");
}

fn init_config() {
    let config_content = r#"# rumdl configuration file

# Global configuration options
[global]
# List of rules to disable (uncomment and modify as needed)
# disable = ["MD013", "MD033"]

# List of rules to enable exclusively (if provided, only these rules will run)
# enable = ["MD001", "MD003", "MD004"]

# List of file/directory patterns to include for linting (if provided, only these will be linted)
# include = [
#    "docs/*.md",
#    "src/**/*.md",
#    "README.md"
# ]

# List of file/directory patterns to exclude from linting
exclude = [
    # Common directories to exclude
    ".git",
    ".github",
    "node_modules",
    "vendor",
    "dist",
    "build",

    # Specific files or patterns
    "CHANGELOG.md",
    "LICENSE.md",
]

# Respect .gitignore files when scanning directories (default: true)
respect-gitignore = true

# Markdown flavor/dialect (uncomment to enable)
# Options: standard (default), gfm, commonmark, mkdocs, mdx, quarto
# flavor = "mkdocs"

# Rule-specific configurations (uncomment and modify as needed)

# [MD003]
# style = "atx"  # Heading style (atx, atx_closed, setext)

# [MD004]
# style = "asterisk"  # Unordered list style (asterisk, plus, dash, consistent)

# [MD007]
# indent = 4  # Unordered list indentation

# [MD013]
# line-length = 100  # Line length
# code-blocks = false  # Exclude code blocks from line length check
# tables = false  # Exclude tables from line length check
# headings = true  # Include headings in line length check

# [MD044]
# names = ["rumdl", "Markdown", "GitHub"]  # Proper names that should be capitalized correctly
# code-blocks = false  # Check code blocks for proper names (default: false, skips code blocks)
"#;
    std::fs::write(".rumdl.toml", config_content).unwrap();
    println!("Created default configuration file: .rumdl.toml");
    println!();
    println!("Setup complete! You can now:");
    println!("  • Run rumdl check . to lint your Markdown files");
    println!("  • Open your editor to see real-time linting");
}

fn list_rules() {
    println!("Available rules:");
    println!("  MD001 - Heading levels should only increment by one level at a time");
    // ... add more
    println!("  MD003 - Heading style");
    println!("  MD004 - Use consistent style for unordered list markers");
    // I should probably read the full list from a file or hardcode it
}

fn show_rule(rule_id: &str) {
    // Mock implementation for now
    println!("Rule: {}", rule_id);
}
EOF
"}

