    Rule { id: "MD062", name: "link-whitespace", description: "Link destination should not have leading or trailing whitespace", fixable: true },
    Rule { id: "MD063", name: "heading-capitalization", description: "Heading capitalization", fixable: false },
    Rule { id: "MD064", name: "multiple-spaces", description: "Multiple consecutive spaces", fixable: true },
    Rule { id: "MD065", name: "blanks-around-hr", description: "Horizontal rules should be surrounded by blank lines", fixable: true },
    Rule { id: "MD066", name: "footnote-validation", description: "Footnote validation", fixable: false },
    Rule { id: "MD067", name: "footnote-order", description: "Footnote definitions should appear in order of first reference", fixable: false },
    Rule { id: "MD068", name: "footnote-empty", description: "Footnote definitions should not be empty", fixable: false },
    Rule { id: "MD069", name: "duplicate-list-markers", description: "Duplicate list markers", fixable: true },
    Rule { id: "MD070", name: "nested-code-fence", description: "Nested code fence collision - use longer fence to avoid premature closure", fixable: true },
    Rule { id: "MD071", name: "blank-line-after-frontmatter", description: "Blank line after frontmatter", fixable: true },
    Rule { id: "MD072", name: "frontmatter-sorted", description: "Frontmatter keys should be sorted alphabetically", fixable: true },
    Rule { id: "MD073", name: "toc-match", description: "Table of Contents should match document headings", fixable: false },
];

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        print_help();
        return;
    }

    match args[1].as_str() {
        "check" => {
            let mut fix = false;
            let mut paths = Vec::new();
            let mut i = 2;
            while i < args.len() {
                match args[i].as_str() {
                    "-f" | "--fix" => fix = true,
                    path if !path.starts_with('-') => paths.push(path),
                    _ => {}
                }
                i += 1;
            }
            if paths.is_empty() {
                paths.push(".");
            }
            run_check(paths, fix);
        }
        "fmt" => {
            let mut paths = Vec::new();
            for i in 2..args.len() {
                if !args[i].starts_with('-') {
                    paths.push(&args[i]);
                }
