struct Issue {
    rule_id: &'static str,
    message: String,
    line: usize,
    column: usize,
    fix: Option<Fix>,
}

struct Fix {
    range: (usize, usize),
    replacement: String,
}

fn lint(content: &str) -> Vec<Issue> {
    let mut issues = Vec::new();
    let lines: Vec<&str> = content.lines().collect();

    // MD047 - Single trailing newline
    if !content.ends_with('\n') {
        issues.push(Issue {
            rule_id: "MD047",
            message: "File should end with a single newline character".to_string(),
            line: lines.len(),
            column: lines.last().map(|l| l.len()).unwrap_or(0) + 1,
            fix: Some(Fix { range: (content.len(), content.len()), replacement: "\n".to_string() }),
        });
    }

    // MD009 - Trailing spaces
    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim_end();
        let diff = line.len() - trimmed.len();
        if diff > 0 && diff != 2 {
            let msg = if diff == 1 { "Trailing space found".to_string() } else { format!("{} trailing spaces found", diff) };
            issues.push(Issue {
                rule_id: "MD009",
                message: msg,
                line: i + 1,
                column: trimmed.len() + 1,
                fix: Some(Fix { range: (get_offset(content, i, trimmed.len()), get_offset(content, i, line.len())), replacement: "".to_string() }),
            });
        }
    }

    // MD041 - First line h1
    if !lines.is_empty() && !lines[0].starts_with("# ") {
        issues.push(Issue {
            rule_id: "MD041",
            message: "First line in file should be a level 1 heading".to_string(),
            line: 1,
            column: 1,
            fix: None,
        });
    }

    issues
}

fn get_offset(content: &str, line_idx: usize, col_idx: usize) -> usize {
    let mut offset = 0;
    for (i, line) in content.lines().enumerate() {
        if i == line_idx {
            return offset + col_idx;
        }
        offset += line.len() + 1; // +1 for \n
    }
    offset
}

fn apply_fixes(content: &str, issues: &[Issue]) -> (String, usize) {
    let mut fixed_content = content.to_string();
    let mut fixed_count = 0;
    let mut offset_adjustment: isize = 0;

    let mut fixable_issues: Vec<&Issue> = issues.iter().filter(|i| i.fix.is_some()).collect();
    // Sort issues by start range to apply them correctly
    fixable_issues.sort_by_key(|i| i.fix.as_ref().unwrap().range.0);

    for issue in fixable_issues {
        if let Some(fix) = &issue.fix {
            let start = (fix.range.0 as isize + offset_adjustment) as usize;
            let end = (fix.range.1 as isize + offset_adjustment) as usize;
            fixed_content.replace_range(start..end, &fix.replacement);
            offset_adjustment += fix.replacement.len() as isize - (fix.range.1 - fix.range.0) as isize;
            fixed_count += 1;
        }
    }

    (fixed_content, fixed_count)
}
