fn main() {
    let start = Instant::now();
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        print_help();
        return;
    }

    match args[1].as_str() {
        "check" => {
            let mut fix = false;
            let mut paths = Vec::new();
            let mut i = 2;
            while i < args.len() {
                match args[i].as_str() {
                    "-f" | "--fix" => fix = true,
                    path if !path.starts_with('-') => paths.push(path),
                    _ => {}
                }
                i += 1;
            }
            if paths.is_empty() {
                paths.push(".");
            }
            run_check(paths, fix, start);
        }
        "fmt" => {
            let mut paths = Vec::new();
            for i in 2..args.len() {
                if !args[i].starts_with('-') {
                    paths.push(&args[i]);
                }
            }
            let paths: Vec<String> = paths.into_iter().map(|s| s.to_string()).collect();
            let paths_ref: Vec<&str> = paths.iter().map(|s| s.as_str()).collect();
            run_check(paths_ref, true, start);
        }
        "init" => {
            init_config();
        }
        "rule" => {
            if args.len() < 3 {
                list_rules();
            } else {
                show_rule(&args[2]);
            }
        }
        "explain" => {
             if args.len() < 3 {
                 eprintln!("error: rule id expected");
                 process::exit(2);
             }
             show_rule(&args[2]);
        }
        "version" | "--version" | "-V" => {
            println!("rumdl 0.1.13");
        }
        "help" | "--help" | "-h" => {
            print_help();
        }
        _ => {
            if args[1].starts_with("-") {
                match args[1].as_str() {
                    "-V" | "--version" => println!("rumdl 0.1.13"),
                    "-h" | "--help" => print_help(),
                    _ => {
                        eprintln!("error: unexpected argument '{}' found", args[1]);
                        process::exit(2);
                    }
                }
            } else {
                eprintln!("error: unknown command '{}'", args[1]);
                process::exit(2);
            }
        }
    }
