fn show_rule(rule_id: &str) {
    if let Some(rule) = RULES.iter().find(|r| r.id == rule_id || r.name == rule_id) {
        println!("{} - {}", rule.id, rule.description);
        println!();
        println!("Name: {}", rule.name);
        println!("Category: heading");
        println!("Fix: {}", if rule.fixable { "Fix is always available." } else { "No automatic fix available." });
        println!("Documentation: https://rumdl.dev/{}/", rule.id.to_lowercase());
    } else {
        eprintln!("error: rule '{}' not found", rule_id);
        process::exit(2);
    }
}

fn run_check(paths: Vec<&str>, fix: bool, start_time: Instant) {
    let mut files = Vec::new();
    for path in &paths {
        let p = Path::new(path);
        if p.exists() {
            find_files(p, &mut files);
        }
    }

    let mut total_issues = 0;
    let mut total_fixed = 0;
    let mut total_fixable = 0;
    let mut checked_files = 0;

    for file in files {
        if let Ok(content) = fs::read_to_string(&file) {
            let issues = lint(&content);
            let file_issues = issues.len();
            let mut file_fixed = 0;
            let file_fixable = issues.iter().filter(|i| i.fix.is_some()).count();

            if fix && file_issues > 0 {
                let (fixed_content, fixed_count) = apply_fixes(&content, &issues);
                fs::write(&file, &fixed_content).unwrap();
                file_fixed = fixed_count;
                for issue in issues {
                    if issue.fix.is_some() {
                         println!("{}:{}:{}: [{}] {} [fixed]", file.display(), issue.line, issue.column, issue.rule_id, issue.message);
                    } else {
                         println!("{}:{}:{}: [{}] {}", file.display(), issue.line, issue.column, issue.rule_id, issue.message);
                    }
                }
            } else {
                for issue in issues {
                    let fix_marker = if issue.fix.is_some() { " [*]" } else { "" };
                    println!("{}:{}:{}: [{}] {}{}", file.display(), issue.line, issue.column, issue.rule_id, issue.message, fix_marker);
                }
            }

            total_issues += file_issues;
            total_fixed += file_fixed;
            total_fixable += file_fixable;
            checked_files += 1;
        }
    }

    let duration = start_time.elapsed();
    let ms = duration.as_millis();

    if fix {
        println!();
        println!("Fixed: Fixed {}/{} issues in {} file{} ({}ms)", total_fixed, total_issues, checked_files, if checked_files == 1 { "" } else { "s" }, ms);
    } else if total_issues > 0 {
        println!();
        println!("Issues: Found {} issues in {} file{} ({}ms)", total_issues, checked_files, if checked_files == 1 { "" } else { "s" }, ms);
        if total_fixable > 0 {
            println!("Run `rumdl fmt` to automatically fix {} of the {} issues", total_fixable, total_issues);
        }
        process::exit(1);
    } else {
        println!();
        println!("Success: No issues found in {} file{} ({}ms)", checked_files, if checked_files == 1 { "" } else { "s" }, ms);
    }
}

fn find_files(path: &Path, files: &mut Vec<PathBuf>) {
    if path.is_file() {
        if path.extension().and_then(|s| s.to_str()) == Some("md") {
            files.push(path.to_path_buf());
        }
    } else if path.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
            let mut sorted_entries: Vec<_> = entries.filter_map(|e| e.ok()).collect();
            sorted_entries.sort_by_key(|e| e.path());
            for entry in sorted_entries {
                let p = entry.path();
                let name = p.file_name().and_then(|n| n.to_str()).unwrap_or("");
                if name == ".git" || name == "node_modules" || name == ".rumdl_cache" {
                    continue;
                }
                find_files(&p, files);
            }
        }
    }
}

struct Issue {
    rule_id: &'static str,
    message: String,
    line: usize,
    column: usize,
    fix: Option<Fix>,
}

struct Fix {
    range: (usize, usize),
    replacement: String,
}

fn lint(content: &str) -> Vec<Issue> {
    let mut issues = Vec::new();
    let lines: Vec<&str> = content.split('\n').collect();
    let mut last_heading_level = 0;
    let mut in_code_block = false;

    for (i, line) in lines.iter().enumerate() {
        let line_num = i + 1;

        if line.starts_with("```") {
            in_code_block = !in_code_block;
            continue;
        }

        if in_code_block {
            continue;
        }

        // MD010 - No tabs
        if line.contains('\t') {
            if let Some(col) = line.find('\t') {
                issues.push(Issue {
                    rule_id: "MD010",
                    message: "No tabs".to_string(),
                    line: line_num,
                    column: col + 1,
                    fix: Some(Fix { range: (get_offset(content, i, col), get_offset(content, i, col + 1)), replacement: "    ".to_string() }),
                });
            }
        }

        // MD009 - Trailing spaces
        let trimmed = line.trim_end();
        let diff = line.len() - trimmed.len();
        if diff > 0 && diff != 2 {
            let msg = if diff == 1 { "Trailing space found".to_string() } else { format!("{} trailing spaces found", diff) };
            issues.push(Issue {
                rule_id: "MD009",
                message: msg,
                line: line_num,
                column: trimmed.len() + 1,
                fix: Some(Fix { range: (get_offset(content, i, trimmed.len()), get_offset(content, i, line.len())), replacement: "".to_string() }),
            });
        }

        // MD013 - Line length
        if line.len() > 80 {
             issues.push(Issue {
                rule_id: "MD013",
                message: format!("Line length {} exceeds 80 characters", line.len()),
                line: line_num,
                column: 81,
                fix: None,
            });
        }

        // MD033 - Inline HTML
        if line.contains("<div") || line.contains("<br") {
             if let Some(start) = line.find('<') {
                if let Some(end) = line[start..].find('>') {
                    let html = &line[start..start+end+1];
                    issues.push(Issue {
                        rule_id: "MD033",
                        message: format!("Inline HTML found: {}", html),
                        line: line_num,
                        column: start + 1,
                        fix: None,
                    });
                }
             }
        }

        // MD030 - Spaces after list markers
        if line.trim_start().starts_with("- ") || line.trim_start().starts_with("* ") || line.trim_start().starts_with("+ ") {
             let marker_pos = line.find(|c| c == '-' || c == '*' || c == '+').unwrap();
             let after_marker = &line[marker_pos+1..];
             let spaces = after_marker.chars().take_while(|c| c.is_whitespace()).count();
             if spaces > 1 {
                 issues.push(Issue {
                     rule_id: "MD030",
                     message: format!("Spaces after list markers (Expected: 1; Actual: {})", spaces),
                     line: line_num,
                     column: marker_pos + 2,
                     fix: Some(Fix { range: (get_offset(content, i, marker_pos + 1), get_offset(content, i, marker_pos + 1 + spaces)), replacement: " ".to_string() }),
                 });
             }
        }

        // Headings
        if line.starts_with('#') {
            let level = line.chars().take_while(|&c| c == '#').count();
            if level > 0 && level <= 6 {
                // MD018 - Space after hash
                if line.len() > level && !line.chars().nth(level).unwrap().is_whitespace() {
                     issues.push(Issue {
                        rule_id: "MD018",
                        message: "No space after hash in heading".to_string(),
                        line: line_num,
                        column: level + 1,
                        fix: Some(Fix { range: (get_offset(content, i, level), get_offset(content, i, level)), replacement: " ".to_string() }),
                    });
                }

                // MD001 - Heading increment
                if last_heading_level > 0 && level > last_heading_level + 1 {
                    issues.push(Issue {
                        rule_id: "MD001",
                        message: format!("Expected heading level {}, but found heading level {}", last_heading_level + 1, level),
                        line: line_num,
                        column: 1,
                        fix: Some(Fix { 
                            range: (get_offset(content, i, 0), get_offset(content, i, level)), 
                            replacement: "#".repeat(last_heading_level + 1) 
                        }),
                    });
                }
                last_heading_level = level;

                // MD022 - Blanks around headings
                if i > 0 && !lines[i-1].is_empty() && !lines[i-1].starts_with("---") {
                    issues.push(Issue {
                        rule_id: "MD022",
                        message: "Expected 1 blank line above heading".to_string(),
                        line: line_num,
                        column: 1,
                        fix: Some(Fix { range: (get_offset(content, i, 0), get_offset(content, i, 0)), replacement: "\n".to_string() }),
                    });
                }
                if i < lines.len() - 1 && !lines[i+1].is_empty() {
                    issues.push(Issue {
                        rule_id: "MD022",
                        message: "Expected 1 blank line below heading".to_string(),
                        line: line_num,
                        column: 1,
                        fix: Some(Fix { range: (get_offset(content, i, line.len()), get_offset(content, i, line.len())), replacement: "\n".to_string() }),
                    });
                }
            }
        }

        // MD035 - Horizontal rule
        if line.trim() == "---" && line.starts_with(' ') {
             issues.push(Issue {
                 rule_id: "MD035",
                 message: "Horizontal rule should not be indented".to_string(),
                 line: line_num,
                 column: 1,
                 fix: Some(Fix { range: (get_offset(content, i, 0), get_offset(content, i, line.find('-').unwrap())), replacement: "".to_string() }),
             });
        }

        // MD012 - Multiple consecutive blank lines
        if i > 0 && line.is_empty() && lines[i-1].is_empty() {
             let mut msg = "Multiple consecutive blank lines".to_string();
             if i == lines.len() - 1 {
                 msg = "Multiple consecutive blank lines at end of file".to_string();
             }
             issues.push(Issue {
                 rule_id: "MD012",
                 message: msg,
                 line: line_num,
                 column: 1,
                 fix: Some(Fix { range: (get_offset(content, i, 0), get_offset(content, i-1, lines[i-1].len() + 1)), replacement: "".to_string() }),
             });
        }
    }

    // MD047 - Single trailing newline
    if !content.is_empty() && !content.ends_with('\n') {
        issues.push(Issue {
            rule_id: "MD047",
            message: "File should end with a single newline character".to_string(),
            line: lines.len(),
            column: lines.last().unwrap_or(&"").len() + 1,
            fix: Some(Fix { range: (content.len(), content.len()), replacement: "\n".to_string() }),
        });
    }

    // MD041 - First line h1
    if !lines.is_empty() && !lines[0].starts_with("# ") && !lines[0].starts_with("---") && !lines[0].is_empty() {
        issues.push(Issue {
            rule_id: "MD041",
            message: "First line in file should be a top level heading".to_string(),
            line: 1,
            column: 1,
            fix: None,
        });
    }

    issues
}

fn get_offset(content: &str, line_idx: usize, col_idx: usize) -> usize {
    let mut offset = 0;
    let lines: Vec<&str> = content.split('\n').collect();
    for i in 0..line_idx {
        offset += lines[i].len() + 1;
    }
    offset + col_idx
}

fn apply_fixes(content: &str, issues: &[Issue]) -> (String, usize) {
    let mut fixed_content = content.to_string();
    let mut fixed_count = 0;

    let mut fixable_issues: Vec<&Issue> = issues.iter().filter(|i| i.fix.is_some()).collect();
    // Sort issues by start range DESCENDING to avoid offset shifting issues
    fixable_issues.sort_by(|a, b| b.fix.as_ref().unwrap().range.0.cmp(&a.fix.as_ref().unwrap().range.0).then(b.fix.as_ref().unwrap().range.1.cmp(&a.fix.as_ref().unwrap().range.1)));

    for issue in fixable_issues {
        if let Some(fix) = &issue.fix {
            if fix.range.0 <= fixed_content.len() && fix.range.1 <= fixed_content.len() {
                fixed_content.replace_range(fix.range.0..fix.range.1, &fix.replacement);
                fixed_count += 1;
            }
        }
    }

    (fixed_content, fixed_count)
}
