        }
        "explain" => {
             if args.len() < 3 {
                 eprintln!("error: rule id expected");
                 process::exit(2);
             }
             show_rule(&args[2]);
        }
        "version" | "--version" | "-V" => {
            println!("rumdl 0.1.13");
        }
        "help" | "--help" | "-h" => {
            print_help();
        }
        _ => {
            if args[1].starts_with("-") {
                match args[1].as_str() {
                    "-V" | "--version" => println!("rumdl 0.1.13"),
                    "-h" | "--help" => print_help(),
                    _ => {
                        eprintln!("error: unexpected argument '{}' found", args[1]);
                        process::exit(2);
                    }
                }
            } else {
                eprintln!("error: unknown command '{}'", args[1]);
                process::exit(2);
            }
        }
    }
}

